from pathlib import Path
import json
from shapely.geometry import LineString,mapping
from shapely.ops import unary_union,linemerge
R=Path(__file__).resolve().parents[1];features=[];provenance=[]
for key,name in [('moscow-canal','Moscow–Volga Canal'),('yakhroma','Yakhroma'),('mius','Mius'),('istra','Istra'),('don','Don')]:
 j=json.loads((R/f'phase-v-maps-review/research/{key}-osm.json').read_text());els=j['elements'];nodes={e['id']:(e['lon'],e['lat']) for e in els if e['type']=='node'};rid={'moscow-canal':1731767,'yakhroma':15886853,'mius':4803477,'istra':2469840,'don':416351}[key];r=next(e for e in els if e['type']=='relation' and e['id']==rid);ids={m['ref'] for m in r['members'] if m['type']=='way' and m.get('role') not in ['tributary','side_stream']};ways=[e for e in els if e['type']=='way' and e['id'] in ids and e.get('tags',{}).get('waterway') in ['canal','river','stream']];lines=[LineString([nodes[n] for n in w['nodes']]) for w in ways if len(w['nodes'])>1];g=unary_union(lines);g=linemerge(g) if g.geom_type=='MultiLineString' else g;g=g.simplify(.0002,preserve_topology=True)
 features.append(dict(type='Feature',geometry=mapping(g),properties=dict(id='p5-water-'+key,name=name,waterwayKind='canal' if key=='moscow-canal' else 'river',sourceIds=['p5-osm-waterways'],sourceLocators={'p5-osm-waterways':[f'OSM relation {rid}, version {r["version"]}; full member/node response recorded in provenance.']},referenceOnly=True,referencePeriod='Modern course orientation; historical existence independently documented',accuracy='Simplified licensed waterway centreline',uncertainty='Modern coordinates are orientation, not 1941 lock, bridge, reservoir, shoreline or water-level geometry.',note=('Canal existed in 1941 under Moscow–Volga name. Engineered course is distinguished from a natural river. ' if key=='moscow-canal' else 'Natural-course orientation; the Don is drawn through its modern impoundments as a centreline, not a 1941 reservoir outline. ' if key=='don' else 'Natural-course orientation; contemporary impoundments are not represented as 1941 reservoir outlines. ')+'No modern crossing, motorway or water-level geometry is imported.')))
 provenance.append(dict(name=name,relation=rid,version=r['version'],ways=len(ways),url=f'https://api.openstreetmap.org/api/0.6/relation/{rid}/full.json',license='© OpenStreetMap contributors, ODbL 1.0',usage='Separately attributed contemporary waterway centreline; 1941 engineering and levels not reconstructed'))
(R/'public/data/geography/phase-v-waterways.geojson').write_text(json.dumps(dict(type='FeatureCollection',features=features),ensure_ascii=False,separators=(',',':'))+'\n');(R/'phase-v-maps-review/waterway-provenance.json').write_text(json.dumps(provenance,indent=2)+'\n')
p=R/'src/data/sources.json';s=json.loads(p.read_text());s=[x for x in s if x['id']!='p5-osm-waterways'];s.append(dict(id='p5-osm-waterways',institution='OpenStreetMap contributors',title='Moscow–Volga Canal, Yakhroma, Mius, Istra and Don waterway centrelines',url='https://www.openstreetmap.org/relation/1731767',date='2026-10-16',type='Licensed physical-geography dataset',supports=['1941-11-15','1941-11-18','1941-11-21','1941-11-24','1941-11-28','1941-11-29','1941-12-02','1941-12-05'],relevance='Canal and natural-watercourse orientation; source IDs and versions saved in review provenance.',notes='Full OSM relations, nodes and member ways inspected. Contemporary centrelines do not prove 1941 water levels, bridge locations or reconstructed reservoir extents.',reuseRights='© OpenStreetMap contributors, ODbL 1.0. Geometry is separately attributed and included in the map/export attribution.'));p.write_text(json.dumps(s,ensure_ascii=False,separators=(',',':'))+'\n');print(provenance)
